from functools import lru_cache
from itertools import combinations_with_replacement

PRICES = {1:800, 2:1520, 3:2160, 4:2560, 5:3000}
MASKS = []
for size in range(1, 6):
    for combo in combinations_with_replacement(range(5), 0):  # placeholder
        pass
for mask in range(1, 32):
    size = mask.bit_count()
    if size <= 5:
        MASKS.append(mask)

@lru_cache(None)
def exact(state):
    state = tuple(sorted(state, reverse=True))
    if not any(state):
        return 0
    best = None
    for mask in MASKS:
        nxt = list(state)
        ok = True
        for i in range(5):
            if mask & (1 << i):
                if nxt[i] == 0:
                    ok = False
                    break
                nxt[i] -= 1
        if not ok:
            continue
        val = PRICES[mask.bit_count()] + exact(tuple(sorted(nxt, reverse=True)))
        if best is None or val < best:
            best = val
    return best

def formula(state):
    a,b,c,d,e = sorted(state, reverse=True)
    g5 = e
    g4 = d-e
    g3 = c-d
    g2 = b-c
    g1 = a-b
    k = min(g5, g3)
    g5 -= k
    g3 -= k
    g4 += 2*k
    return g5*3000 + g4*2560 + g3*2160 + g2*1520 + g1*800

bad = []
limit = 8
for state in combinations_with_replacement(range(limit+1), 5):
    state = tuple(sorted(state, reverse=True))
    ex = exact(state)
    fo = formula(state)
    if ex != fo:
        bad.append((state, ex, fo))
print('states', len(list(combinations_with_replacement(range(limit+1), 5))), 'mismatches', len(bad))
for item in bad[:30]:
    print(item)
