import { cost } from './book-store.mjs';

const prices = [0, 800, 1520, 2160, 2560, 3000];
const masks = Array.from({ length: 31 }, (_, i) => i + 1);
const memo = new Map();

function key(state) { return state.join(','); }

function optimal(counts) {
  const state = [...counts].sort((a, b) => b - a);
  const k = key(state);
  if (memo.has(k)) return memo.get(k);
  if (state.every((n) => n === 0)) return 0;

  let best = Infinity;
  for (const mask of masks) {
    const next = [...state];
    let valid = true;
    let size = 0;
    for (let i = 0; i < 5; i++) {
      if (mask & (1 << i)) {
        size++;
        if (next[i] === 0) { valid = false; break; }
        next[i]--;
      }
    }
    if (valid) {
      best = Math.min(best, prices[size] + optimal(next));
    }
  }
  memo.set(k, best);
  return best;
}

function basketFrom(counts) {
  const basket = [];
  counts.forEach((n, i) => { for (let j = 0; j < n; j++) basket.push(i + 1); });
  return basket;
}

function shuffle(items) {
  const result = [...items];
  for (let i = result.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [result[i], result[j]] = [result[j], result[i]];
  }
  return result;
}

let checked = 0;
for (let a = 0; a <= 10; a++) {
  for (let b = 0; b <= a; b++) {
    for (let c = 0; c <= b; c++) {
      for (let d = 0; d <= c; d++) {
        for (let e = 0; e <= d; e++) {
          const counts = [a, b, c, d, e];
          const expected = optimal(counts);
          const actual = cost(shuffle(basketFrom(counts)));
          if (actual !== expected) {
            throw new Error(`Mismatch for ${counts}: ${actual} != ${expected}`);
          }
          checked++;
        }
      }
    }
  }
}

for (let trial = 0; trial < 2000; trial++) {
  const counts = Array.from({ length: 5 }, () => Math.floor(Math.random() * 16)).sort((a, b) => b - a);
  const expected = optimal(counts);
  const actual = cost(shuffle(basketFrom(counts)));
  if (actual !== expected) {
    throw new Error(`Random mismatch for ${counts}: ${actual} != ${expected}`);
  }
}

const large = cost(Array.from({ length: 5000 }, (_, i) => (i % 5) + 1));
if (large !== 3000000) throw new Error(`Unexpected large basket price: ${large}`);
console.log(`Actual implementation checked ${checked} exhaustive and 2000 random baskets; all optimal. Large basket: ${large} cents.`);
EOF
